export const KEY='careerpilot-v1';
export function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
export function normalizeJob(j){if(!j||typeof j!=='object'||!String(j.title||'').trim()||!String(j.description||'').trim())throw Error('A job needs a title and description.');return {id:crypto.randomUUID(),title:String(j.title).slice(0,200),company:String(j.company||'Company').slice(0,200),location:String(j.location||'Not specified').slice(0,200),url:safeURL(j.url),description:String(j.description).slice(0,60000),status:'Saved',createdAt:new Date().toISOString()}}
export function tailor(profile,job){const skills=String(profile.skills||'').split(',').map(s=>s.trim()).filter(Boolean);const text=job.description.toLowerCase();const has=s=>text.includes(s.toLowerCase());const matched=skills.filter(has),missing=skills.filter(s=>!has(s));const lines=String(profile.resume||'').split('\n').filter(s=>s.trim());const score=s=>matched.reduce((n,k)=>n+(s.toLowerCase().includes(k.toLowerCase())?1:0),0);const ranked=lines.map((text,index)=>({text,index,score:score(text)})).sort((a,b)=>b.score-a.score||a.index-b.index);return {matched,other:missing,text:[profile.fullName||'Your name',[profile.email,profile.phone,profile.location].filter(Boolean).join(' | '),profile.linkedin||'',`\nAPPLICATION: ${job.title} — ${job.company}`,matched.length?`\nRELEVANT SKILLS\n${matched.join(' · ')}`:'',`\nEXPERIENCE & QUALIFICATIONS\n${ranked.map(r=>r.text).join('\n')}`,missing.length?`\nADDITIONAL SKILLS\n${missing.join(' · ')}`:''].filter(Boolean).join('\n')}}
